<?php foreach($pi as $r): ?><tr><td><b><?=h($r['nombre'])?></b></td><td><?=nf($r['m3'])?></td><td><?=nf($r['m3']/$tot*100,1)?> %</td><td style="color:var(--ok)">↘ <?=nf(abs($r['var']),1)?> %</td><td>$<?=nf($r['m3']*$tar)?></td></tr><?php endforeach ?></table></div>
